"""Build Trip Bhai's dependency-free public website from its approved company content."""
from pathlib import Path
from html import escape
import json
ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / 'public-pages'
PORTAL = 'https://beyond-travel-portfolio.saintblue022.chatgpt.site'
TEAM = [('ZR Saimon','Founder','ZR'),('Riazul Iqbal Feroz','Dubai Country Manager','RF'),('Umme Sumaiya','Director, Client Relations','US'),('Aumlanul Abrar','Director of UK Operations & Technology','AA')]
NAV = [('about','Our company'),('visa-services','Visa enquiries'),('flights-travel','Travel planning'),('team','Our people'),('visa-successes','Visa stories'),('contact','Contact')]
def link(path, label, cls='button', prefix=''):
    return f'<a class="{cls}" href="{prefix}{path}/">{label}</a>'
def heading(kicker,title,description):
    return f'<section class="page-head wrap"><p class="eyebrow">{kicker}</p><h1>{title}</h1><p class="lead">{description}</p></section>'
def people():
    return '<div class="people">'+''.join(f'<article class="person"><span class="monogram" aria-hidden="true">{i}</span><h3>{n}</h3><p>{r}</p></article>' for n,r,i in TEAM)+'</div>'
def cta(p):
    return f'<section class="wrap"><div class="cta"><div><p class="eyebrow">LET’S TALK ABOUT YOUR PLANS</p><h2>Your next journey<br>starts here.</h2></div>{link("contact","Talk to Trip Bhai ↗",prefix=p)}</div></section>'
def page(slug,title,desc,body):
    p='../' if slug else './'
    nav=''.join(f'<a href="{p}{s}/"'+(' aria-current="page"' if s==slug else '')+f'>{n}</a>' for s,n in NAV)
    schema={'@context':'https://schema.org','@type':'TravelAgency','name':'Trip Bhai','legalName':'TRIP BHAI LTD','url':'https://tripbhai.co.uk/','email':'tripbhaiofficial@gmail.com','telephone':'+447514718031','identifier':'16286072'}
    html=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} | Trip Bhai</title><meta name="description" content="{escape(desc,quote=True)}"><meta name="theme-color" content="#122d30"><link rel="canonical" href="https://tripbhai.co.uk/{slug+'/' if slug else ''}"><meta property="og:title" content="{title} | Trip Bhai"><meta property="og:description" content="{escape(desc,quote=True)}"><meta property="og:type" content="website"><link rel="icon" href="{p}assets/favicon.svg"><link rel="stylesheet" href="{p}site.css"><script src="{p}site.js" defer></script><script type="application/ld+json">{json.dumps(schema)}</script></head><body>
<a class="skip" href="#main">Skip to content</a><div class="utility"><div class="wrap"><span>TRIP BHAI LTD · LONDON</span><a href="tel:+447514718031">+44 7514 718031</a></div></div>
<header class="header"><div class="wrap navigation"><a class="brand" href="{p}" aria-label="Trip Bhai home"><img src="{p}assets/trip-bhai-logo.png" width="44" height="44" alt=""><span>Trip<span class="accent">Bhai</span><small>TRAVEL. WITH A PERSONAL TOUCH.</small></span></a><button id="menu" class="menu" aria-expanded="false" aria-controls="navigation">Menu</button><nav id="navigation" aria-label="Main navigation">{nav}</nav></div></header>
<main id="main">{body}{cta(p) if slug!='contact' else ''}</main>
<footer class="footer"><div class="wrap"><div class="footer-top"><div><a class="footer-brand" href="{p}">Trip Bhai<span>ভ্রমণের সঙ্গী</span></a><p>Visit visa enquiries. Thoughtful travel planning.<br>A personal point of contact.</p></div><div><h2>Get in touch</h2><a href="mailto:tripbhaiofficial@gmail.com">tripbhaiofficial@gmail.com</a><a href="tel:+447514718031">+44 7514 718031</a><a href="{PORTAL}/client-login">Client portal ↗</a></div><div><h2>Explore</h2><a href="{p}visa-successes/">Visa stories</a><a href="{p}about/">Company details</a><a href="{p}uk-support/">Service availability</a><a href="{p}privacy-terms/">Privacy &amp; service terms</a></div></div><div class="legal"><p>© {2026} TRIP BHAI LTD · Company no. 16286072<br>Registered in England and Wales · Incorporated 3 March 2025<br>Website last updated 11 November 2026</p><p>Registered office: 53 Blenheim Road, London, England, E6 3EG.<br>Please arrange an appointment and confirm the meeting location before travelling.</p><a href="https://find-and-update.company-information.service.gov.uk/company/16286072">View company record ↗</a></div></div></footer></body></html>'''
    dest=OUT/slug if slug else OUT
    dest.mkdir(parents=True,exist_ok=True)
    (dest/'index.html').write_text(html)
p='./'
home='''<section class="hero wrap"><div class="hero-copy"><p class="eyebrow">LONDON ROOTS. YOUR WORLD AHEAD.</p><h1>Every journey<br>starts with<br><em>a conversation.</em></h1><p class="lead">Visit visa enquiries, flights and travel plans — brought together by the people at Trip Bhai. Tell us where you want to go. We’ll help you work out the next step.</p><div class="actions"><a class="button" href="./contact/">Let’s plan your journey ↗</a><a class="text-link" href="./about/">Meet your travel team →</a></div><p class="bengali" lang="bn">আপনার ভ্রমণ, আমাদের যত্ন।</p></div><figure class="hero-image"><img src="./assets/amalfi.jpg" alt="The colourful coastline of Positano, Italy" fetchpriority="high" width="960" height="1200"><figcaption><span>PLACES TO IMAGINE</span>Italy, at your own pace.</figcaption><span class="image-stamp" aria-hidden="true">A WORLD<br>OF POSSIBILITIES ↗</span></figure></section>
<section class="intro-strip"><div class="wrap"><span>01 / VISIT VISA ENQUIRIES</span><span>02 / FLIGHTS & STAYS</span><span>03 / PERSONALISED TRIPS</span></div></section>
<section class="section wrap split"><div><p class="eyebrow">THIS IS TRIP BHAI</p><h2>A travel company.<br><em>A human connection.</em></h2></div><div><p class="lead">Trip Bhai is the public brand of TRIP BHAI LTD, a London-based travel agency incorporated in March 2025.</p><p>Our focus is straightforward: understand your plans, explain the scope of the support available and agree the next steps with you. From a visit visa enquiry to a flight or a tailored trip, it begins with your circumstances.</p><a class="text-link" href="./about/">Get to know our company →</a></div></section>
<section class="section services-bg"><div class="wrap"><div class="section-title"><div><p class="eyebrow">WHAT BRINGS YOU HERE?</p><h2>One team.<br><em>A few ways forward.</em></h2></div><p>Choose a starting point. We’ll confirm the service, availability and quotation before you decide.</p></div><div class="service-list"><a href="./visa-services/"><span>01</span><div><h3>Visit visa enquiries</h3><p>Talk through your destination, travel dates and the support you’re looking for.</p></div><b aria-hidden="true">↗</b></a><a href="./flights-travel/"><span>02</span><div><h3>Flights, hotels & holidays</h3><p>Share your route, budget and preferences for a personalised travel enquiry.</p></div><b aria-hidden="true">↗</b></a><a href="./uk-support/"><span>03</span><div><h3>UK support & future services</h3><p>See what is planned and the current limits of our service.</p></div><b aria-hidden="true">↗</b></a></div></div></section>
<section class="section wrap"><div class="section-title"><div><p class="eyebrow">THE PEOPLE BEHIND THE NAME</p><h2>Your plans.<br><em>Our people.</em></h2></div><a class="text-link" href="./team/">Meet the team →</a></div>'''+people()+'''</section>
<section class="section wrap editorial"><img src="./assets/cappadocia.jpg" alt="Hot-air balloons over Cappadocia, Türkiye" loading="lazy" width="1000" height="700"><div><p class="eyebrow">SOMETHING TO LOOK FORWARD TO</p><h2>A familiar place.<br>Or somewhere<br><em>entirely new.</em></h2><p>A family visit, a city break or a longer adventure. Tell us what matters to you and we’ll shape the enquiry around it.</p><a class="text-link" href="./flights-travel/">Explore travel planning →</a><small>Destination photography is inspiration, not a bookable offer.</small></div></section>
<section class="section wrap"><p class="eyebrow">HOW WE BEGIN</p><h2>Clear steps.<br><em>From the first hello.</em></h2><div class="steps"><article><span>01</span><h3>Tell us your plans</h3><p>Your destination, dates and a way to reach you. No passport or financial documents at this stage.</p></article><article><span>02</span><h3>Agree the scope</h3><p>We confirm what support is available, what it includes and the quotation before work begins.</p></article><article><span>03</span><h3>Take the next step</h3><p>Follow the agreed instructions. An enquiry is not a confirmed booking or a visa application.</p></article></div></section>'''
page('','Travel & visit visa enquiries', 'Meet Trip Bhai: London-based TRIP BHAI LTD. Visit visa enquiries, flights, hotels and personalised travel planning. Contact our real team.',home)
page('about','Our company','About TRIP BHAI LTD, company 16286072: our travel focus, public contact details and registered office.',heading('OUR COMPANY','Meet <em>Trip Bhai.</em>','A London-based travel agency with a personal approach to visit visa enquiries and travel planning.')+'''<section class="wrap section split"><div><h2>Built around<br><em>your plans.</em></h2><p>Trip Bhai brings visit visa enquiries, air-ticket enquiries, hotel stays and personalised travel planning into one conversation. We start by understanding your destination and what help you need.</p><p>We agree the service scope and costs before work begins. Travel prices and availability are confirmed separately; visa decisions rest with the relevant authorities.</p><a class="text-link" href="../team/">Meet the people behind Trip Bhai →</a></div><div class="company-panel"><p class="eyebrow">COMPANY INFORMATION</p><dl><dt>Legal name</dt><dd>TRIP BHAI LTD</dd><dt>Company number</dt><dd>16286072</dd><dt>Company type</dt><dd>Private limited company</dd><dt>Incorporated</dt><dd>3 March 2025</dd><dt>Registered office</dt><dd>53 Blenheim Road, London, England, E6 3EG</dd><dt>Nature of business</dt><dd>Travel agency activities (SIC 79110)</dd></dl><a class="text-link" href="https://find-and-update.company-information.service.gov.uk/company/16286072">Check the public register ↗</a></div></section><section class="wrap note"><h2>Before visiting</h2><p>The registered office is our legal correspondence address. Please contact the team to arrange an appointment and confirm your meeting location before travelling.</p></section>''')
page('team','Our people','Meet ZR Saimon, Riazul Iqbal Feroz, Umme Sumaiya and Aumlanul Abrar: the Trip Bhai team.',heading('OUR PEOPLE','The names behind<br><em>your next chapter.</em>','Meet the people behind Trip Bhai, from our founder to client relations and operations.')+'<section class="wrap section">'+people()+'''<div class="note"><h2>Start with the team</h2><p>Use our shared contact details for a new enquiry. Tell us the service and destination you have in mind so your conversation can reach the right person.</p><a class="text-link" href="mailto:tripbhaiofficial@gmail.com">tripbhaiofficial@gmail.com →</a></div></section>''')
page('visa-services','Visit visa enquiries','Start a visit visa enquiry with Trip Bhai. Destination-specific next steps, clear scope and no guaranteed outcomes.',heading('VISIT VISA ENQUIRIES','A new destination.<br><em>A clear first step.</em>','Tell us where you want to travel, when you hope to go and what support you need. We’ll confirm whether we can help and explain the next steps.')+'''<section class="wrap section split"><div><h2>Start with your<br><em>destination.</em></h2><p>Our travel brief covers Schengen and Ireland visit enquiries, as well as other international destinations. Requirements depend on the destination and your circumstances; a checklist is confirmed individually.</p><p>Ireland and the Schengen Area are separate destinations for visa purposes. We do not treat their application requirements as interchangeable.</p><p>UK immigration advice and representation are not currently offered through this public site. See our <a href="../uk-support/">UK support information</a>.</p></div><div class="company-panel"><h2>What to tell us</h2><ul><li>Your destination and the purpose of your visit</li><li>Approximate travel dates</li><li>The type of support you are looking for</li><li>Your name and preferred contact details</li></ul><p>Please do not send passport scans, bank statements or other sensitive documents in your initial enquiry.</p><a class="button" href="../contact/?service=Visit%20visa%20enquiry">Start a visa enquiry ↗</a></div></section><section class="wrap section faq"><h2>A few helpful answers.</h2><details><summary>Does an enquiry submit my visa application?</summary><p>No. It starts a conversation with Trip Bhai. An application to an embassy or authority is a separate step.</p></details><details><summary>Can Trip Bhai guarantee an approval?</summary><p>No. Decisions are made by the relevant authorities. A previous approval is not a guarantee for another application.</p></details><details><summary>What does the service cost?</summary><p>We confirm the scope and quotation for your enquiry before work begins. No fee or processing time is promised on this page.</p></details><details><summary>Where can I see visa stories?</summary><p>Visit our <a href="../visa-successes/">visa stories page</a>. Individual outcomes should never be treated as a prediction for your own case.</p></details></section>''')
page('flights-travel','Flights & travel planning','Personalised flight, hotel and holiday enquiries with Trip Bhai. Share your dates, preferences and budget.',heading('FLIGHTS · STAYS · TAILORED TRIPS','Make room<br><em>for the journey.</em>','A flight home, a few nights away or a trip with more moving parts. Let’s start with what you have in mind.')+'''<section class="wrap section editorial"><img src="../assets/london.jpg" alt="Westminster and the Houses of Parliament in London" width="1000" height="700" loading="lazy"><div><p class="eyebrow">A PLAN THAT STARTS WITH YOU</p><h2>Where, when<br><em>and your way.</em></h2><p>For flights, share your departure airport, destination, travel dates, passenger numbers, cabin and baggage preferences.</p><p>For a stay or holiday, tell us your budget, preferred location, length of stay and anything that matters to your travelling party.</p><a class="button" href="../contact/?service=Flights%20and%20travel">Plan my trip ↗</a></div></section><section class="wrap note"><h2>Enquiries, then confirmed options</h2><p>This website does not display live fares or take booking payments. The team confirms availability, prices, supplier terms and the next steps separately. Sending an enquiry does not reserve a flight or hotel.</p></section>''')
page('uk-support','UK support','Current availability of Trip Bhai’s planned UK orientation and application services.',heading('SERVICE AVAILABILITY','Practical support.<br><em>Clear boundaries.</em>','Our planned UK support services have a defined scope. Please check availability with the team before making arrangements.')+'''<section class="section wrap"><div class="steps"><article><span>PLANNED</span><h2>UK orientation</h2><p>One-to-one practical mentoring and administrative support are part of our service plans. Appointments are not advertised as available until confirmed by the team.</p></article><article><span>NOT CURRENTLY AVAILABLE</span><h2>UK immigration advice</h2><p>UK visa, Graduate visa (PSW), ILR advice, application selection and representation remain unavailable pending verification of the responsible adviser’s authorisation and permitted scope.</p><a href="https://www.gov.uk/find-an-immigration-adviser">Find an authorised immigration adviser ↗</a></article><article><span>PLANNED</span><h2>Wellbeing support</h2><p>Non-clinical practical support is planned. This is not therapy, clinical care or crisis support, and no appointments are currently advertised.</p></article></div></section>''')
gallery = '<section class="wrap section"><div class="gallery">'+''.join(f'<figure><img src="../assets/visa-successes/success-{i:02}.jpg" alt="Client-shared visa outcome photograph {i}" loading="lazy"><figcaption>Client-shared visa outcome</figcaption></figure>' for i in range(1,8))+'</div><div class="note"><h2>Individual decisions, shared with permission</h2><p>These photographs were previously supplied for Trip Bhai’s public gallery. They do not establish a success rate or predict another decision. For a photo removal request, email <a href="mailto:tripbhaiofficial@gmail.com">tripbhaiofficial@gmail.com</a>.</p></div></section>'
